e[0],\n          Map.of());\n    }\n    if (value instanceof BigInt big)\n    {\n      return big.toBigInteger();\n    }\n    return value;\n  }\n\n  private static Object data(\n      IPersistentMap map, Class<?> expected, Type[] arguments, Map<TypeVariable<?>, Type> bound)\n  {\n    Class<?> record;\n    var tag = map.valAt(TAG);\n    if (expected.isRecord())\n    {\n      record = expected;\n    }\n    else if (tag instanceof Keyword keyword)\n    {\n      record = classOfTag(keyword);\n      if (!expected.isAssignableFrom(record))\n      {\n        throw new IllegalArgumentException(keyword + \" is not a \" + expected.getSimpleName());\n      }\n    }\n    else\n    {\n      throw new IllegalArgumentException(\n          \"a \" + expected.getSimpleName() + \" needs a :lawspec/tag: \" + RT.printString(map));\n    }\n    var variables = new HashMap<TypeVariable<?>, Type>(bound);\n    TypeVariable<?>[] own = expected.getTypeParameters();\n    // Arguments are resolved first, so no variable stands for itself.\n    for (int i = 0; i < own.length && i < arguments.length; i++)\n    {\n      variables.put(own[i], resolve(arguments[i], bound));\n    }\n    if (record != expected)\n    {\n      // A case's type parameters are its sum's, by the sum it implements.\n      for (Type implemented : record.getGenericInterfaces())\n      {\n        if (implemented instanceof ParameterizedType p && p.getRawType() == expected)\n        {\n          Type[] actual = p.getActualTypeArguments();\n          for (int i = 0; i < actual.length && i < own.length; i++)\n          {\n            if (actual[i] instanceof TypeVariable<?> v && variables.containsKey(own[i]))\n            {\n              variables.put(v, variables.get(own[i]));\n            }\n          }\n        }\n      }\n    }\n    RecordComponent[] components = record.getRecordComponents();\n    var types = new Class<?>[components.length];\n    var values = new Object[components.length];\n    for (int i = 0; i < components.