clojureSource "java-test/lawspec/testing/check/Assertions.java" = "// Generated by LawSpec. Do not edit.\n\npackage lawspec.testing.check;\n\nimport java.util.Objects;\nimport java.util.function.Supplier;\n\n/** The assertions the generated law cases use, failing with AssertionError. */\npublic final class Assertions\n{\n  private Assertions()\n  {}\n\n  public static void assertTrue(boolean condition, Supplier<String> message)\n  {\n    if (!condition)\n    {\n      throw new AssertionError(message.get());\n    }\n  }\n\n  public static void assertTrue(boolean condition, String message)\n  {\n    if (!condition)\n    {\n      throw new AssertionError(message);\n    }\n  }\n\n  public static void assertTrue(boolean condition)\n  {\n    if (!condition)\n    {\n      throw new AssertionError(\"expected true\");\n    }\n  }\n\n  public static void assertFalse(boolean condition)\n  {\n    if (condition)\n    {\n      throw new AssertionError(\"expected false\");\n    }\n  }\n\n  public static void assertFalse(boolean condition, String message)\n  {\n    if (condition)\n    {\n      throw new AssertionError(message);\n    }\n  }\n\n  public static void assertNull(Object value)\n  {\n    if (value != null)\n    {\n      throw new AssertionError(\"expected null, got \" + value);\n    }\n  }\n\n  public static void assertEquals(Object expected, Object actual)\n  {\n    if (!Objects.equals(expected, actual))\n    {\n      throw new AssertionError(\"expected \" + expected + \", got \" + actual);\n    }\n  }\n\n  public static void assertEquals(Object expected, Object actual, String message)\n  {\n    if (!Objects.equals(expected, actual))\n    {\n      throw new AssertionError(message + \": expected \" + expected + \", got \" + actual);\n    }\n  }\n\n  public static void assertArrayEquals(byte[] expected, byte[] actual)\n  {\n    if (!java.util.Arrays.equals(expected, actual))\n    {\n      throw new AssertionError(\"arrays differ\");\n    }\n  }\n}\n"
clojureSource "java-test/lawspec/testing/check/Draws.java" = "// Generated by LawSpec. Do not edit.\n\npackage lawspec.testing.check;\n\nimport java.util.ArrayList;\nimport java.util.Iterator;\nimport java.util.List;\nimport java.util.NoSuchElementException;\nimport java.util.Random;\n\n/**\n * The choices of one generated case. A fresh choice is random, drawn more often at a range's ends\n * and near zero; a replayed one comes from a recorded sequence, clamped into the range the\n * generator now asks for.\n */\npublic final class Draws implements GenerationEnvironment\n{\n  private final Random random;\n  private final int sizeHint;\n  private final List<Integer> replayed;\n  private final List<int[]> trace = new ArrayList<>();\n\n  Draws(Random random, int sizeHint, List<Integer> replayed)\n  {\n    this.random = random;\n    this.sizeHint = sizeHint;\n    this.replayed = replayed;\n  }\n\n  @Override\n  public <T> T generate(Generator<T> generator)\n  {\n    return generator.generateValue(this);\n  }\n\n  @Override\n  public int getSizeHint()\n  {\n    return sizeHint;\n  }\n\n  /** One integer in min..max. */\n  public int draw(int min, int max)\n  {\n    int position = trace.size();\n    int value =\n        position < replayed.size()\n            ? (int) Math.max(min, Math.min(max, (long) replayed.get(position)))\n            : fresh(min, max);\n    trace.add(new int[] {min, max, value});\n    return value;\n  }\n\n  private int fresh(int min, int max)\n  {\n    long span = (long) max - min + 1;\n    switch (random.nextInt(16))\n    {\n      case 0:\n        return min;\n      case 1:\n        return max;\n      case 2:\n        return clamp(0, min, max);\n      case 3:\n        return clamp(1, min, max);\n      case 4:\n        return clamp(-1, min, max);\n      case 5:\n      case 6:\n      case 7:\n      {\n        long near = random.nextInt(2 * Math.max(1, sizeHint) + 1) - Math.max(1, sizeHint);\n        return clamp(near, min, max);\n      }\n      default:\n        return (int) (min + (long) (random.nextDouble() * span));\n    }\n  }\n\n  private static int clamp(long value, int min, int max)\n  {\n    return (int) Math.max(min, Math.min(max, value));\n  }\n\n  /** A generated value and the rose tree of its shrinks. */\n  public static final class Case<T>\n  {\n    private final Generator<T> generator;\n    private final int size;\n    private final List<int[]> trace;\n    private final T value;\n\n    private Case(Generator<T> generator, int size, List<int[]> trace, T value)\n    {\n      this.generator = generator;\n      this.size = size;\n      this.trace = trace;\n      this.value = value;\n    }\n\n    /** A fresh case from a seed and a size. */\n    public static <T> Case<T> generate(Generator<T> generator, long seed, int size)\n    {\n      // Collections may grow from the start: test.check's first sizes are 0.\n      size = size + 10;\n      var draws = new Draws(new Random(seed), size, List.of());\n      T value = generator.generateValue(draws);\n      return new Case<>(generator, size, draws.trace, value);\n    }\n\n    public T value()\n    {\n      return value;\n    }\n\n    /**\n     * The smaller cases, made lazily: runs of choices dropped (shorter lists, fewer parts), then\n     * each choice moved toward zero. A candidate the generator cannot make again, as a refinement's\n     * filter rejects it, is no shrink.\n     */\n    public Iterator<Case<T>> shrinks()\n    {\n      List<Integer> choices = new ArrayList<>(trace.size());\n      for (int[] choice : trace)\n      {\n        choices.add(choice[2]);\n      }\n      List<List<Integer>> candidates = new ArrayList<>();\n      for (int chunk : new int[] {8, 4, 2, 1})\n      {\n        for (int start = 0; start + chunk <= choices.size(); start++)\n        {\n          var candidate = new ArrayList<>(choices.subList(0, start));\n          candidate.addAll(choices.subList(start + chunk, choices.size()));\n          candidates.add(candidate);\n        }\n      }\n      for (int index = 0; index < choices.size(); index++)\n      {\n        for (int smaller :\n            towardZero(choices.get(index), trace.get(index)[0], trace.get(index)[1]))\n        {\n          var candidate = new ArrayList<>(choices);\n          candidate.set(index, smaller);\n          candidates.add(candidate);\n        }\n      }\n      Iterator<List<Integer>> pending = candidates.iterator();\n      return new Iterator<>()\n      {\n        private Case<T> next;\n\n        @Override\n        public boolean hasNext()\n        {\n          while (next == null && pending.hasNext())\n          {\n            next = replay(pending.next());\n          }\n          return next != null;\n        }\n\n        @Override\n        public Case<T> next()\n        {\n          if (!hasNext())\n          {\n            throw new NoSuchElementException();\n          }\n          var found = next;\n          next = null;\n          return found;\n        }\n      };\n    }\n\n    private Case<T> replay(List<Integer> choices)\n    {\n      var draws = new Draws(new Random(0), size, choices);\n      try\n      {\n        T replayedValue = generator.generateValue(draws);\n        return smaller(draws.trace, trace)\n            ? new Case<>(generator, size, draws.trace, replayedValue)\n            : null;\n      }\n      catch (RuntimeException rejected)\n      {\n        return null;\n      }\n    }\n\n    // Fewer choices, or as many with smaller magnitudes earlier.\n    private static boolean smaller(List<int[]> a, List<int[]> b)\n    {\n      if (a.size() != b.size())\n      {\n        return a.size() < b.size();\n      }\n      for (int i = 0; i < a.size(); i++)\n      {\n        long x = Math.abs((long) a.get(i)[2]);\n        long y = Math.abs((long) b.get(i)[2]);\n        if (x != y)\n        {\n          return x < y;\n        }\n        if (a.get(i)[2] != b.get(i)[2])\n        {\n          return a.get(i)[2] > b.get(i)[2];\n        }\n      }\n      return false;\n    }\n\n    private static List<Integer> towardZero(int value, int min, int max)\n    {\n      long target = Math.max(min, Math.min(max, 0));\n      var out = new ArrayList<Integer>();\n      if (value == target)\n      {\n        return out;\n      }\n      out.add((int) target);\n      long distance = (long) value - target;\n      for (long step = distance / 2; step != 0; step /= 2)\n      {\n        out.add((int) (value - step));\n      }\n      out.add((int) (value - Long.signum(distance)));\n      return out;\n    }\n  }\n}\n"
